-- Publishes a new Privacy Policy version for live verification: one camera
-- photo, a selfie OR a government-issued ID (migration 20).
--
-- The text is a verbatim copy of frontend/src/features/info/pages/legalDocuments.js
-- (generated from it; regenerate rather than hand-edit if the wording changes
-- before this is first applied anywhere). Published silently, like migration 16:
-- requiresAcknowledgement = false, so nobody is put behind the update screen.
-- The previous version is archived, never deleted. No CONCURRENTLY, no
-- schema-qualified names.

UPDATE "LegalDocumentVersion"
SET "isCurrent" = false, "status" = 'ARCHIVED', "updatedAt" = CURRENT_TIMESTAMP
WHERE "documentType" = 'PRIVACY_POLICY' AND "isCurrent" = true;

INSERT INTO "LegalDocumentVersion" (
  "id","documentType","versionNumber","title","subtitle","content","status",
  "isCurrent","requiresAcknowledgement","changeSummary","effectiveAt",
  "createdById","createdAt","updatedAt","publishedById","publishedAt"
)
SELECT
  gen_random_uuid()::text, 'PRIVACY_POLICY',
  COALESCE((SELECT max("versionNumber") FROM "LegalDocumentVersion" WHERE "documentType" = 'PRIVACY_POLICY'), 0) + 1,
  $legal$Privacy Policy$legal$, $legal$How Meetifyy collects, uses, and protects your personal data.$legal$,
  $legal$<h2>1. Introduction</h2><p>Welcome to Meetifyy ("Meetifyy," "we," "our," or "us"). This Privacy Policy describes how we collect, use, and handle your personal information when you use the Meetifyy platform, including our website, web application, and related services (collectively, the "Platform").</p><p>By creating an account or using the Platform, you acknowledge that you have read and understood this policy. If you have any questions, please contact us using the details at the end of this document.</p><h2>2. Personal Data We Collect</h2><p>We collect personal information in the following categories:</p><h3>Data You Provide Directly</h3><ul><li><strong>Account Information:</strong> Your full name, username, email address, date of birth, gender, and password when you register.</li><li><strong>Personal Email:</strong> If you add a personal email address in Settings, that address, which then becomes the email you sign in with.</li><li><strong>College Email and Affiliation:</strong> If you verify your college on the Campus page, the official college email address you provide, the college you select, and when it was verified.</li><li><strong>Verification Image:</strong> If you complete account verification, the one photo you choose to take with your device's camera: either a live selfie or a live photo of a government-issued identity document. Verification photos can only be taken with the camera, not uploaded from your files. When we receive the photo we re-process it, which removes any location or device information embedded in it.</li><li><strong>Academic Details:</strong> Your course, branch, and current year of study, and the college or university you verify.</li><li><strong>Profile Data:</strong> Your bio, profile photo, cover image, interests, and any other information you choose to add to your profile.</li><li><strong>User-Generated Content:</strong> Posts, comments, messages, media uploads, communities you join or create, events you create or attend, and reports you submit.</li><li><strong>Support Communications:</strong> Your name, email address, and any information you include when contacting our support team.</li></ul><h3>Data Collected Automatically</h3><ul><li><strong>Server Logs:</strong> Our servers may record IP addresses, request timestamps, and other standard HTTP log data as part of routine infrastructure operation and security monitoring.</li></ul><h3>Browser Storage</h3><p>We use browser-side storage technologies (localStorage, sessionStorage, IndexedDB, and Service Worker caches) to keep you signed in, remember your preferences, and make the Platform faster. We do not use tracking cookies, web beacons, or any advertising tracking technologies. We do use cookieless analytics on the website to count page views and measure page speed, which store nothing on your device, and we send anonymised error reports to Sentry (see our Cookie Policy). Signing in sets strictly necessary session cookies on the website. For full details, see our <a href="/cookie-policy">Cookie Policy</a>.</p><h2>3. How We Use Your Data</h2><p>We use your personal information for the following purposes:</p><ul><li><strong>Account and Service Delivery:</strong> To create and manage your account, verify the email addresses you add, confirm your college affiliation for Campus access, connect you with campus communities and events, and provide direct messaging.</li><li><strong>Account Verification:</strong> To review the live selfie or the live photo of your government-issued identity document that you submit, so we can confirm you are a real person before enabling messaging, posting, creating communities and activities, and Instant Match. Verification photos are stored privately, are never shown to other users, and are viewed only by authorised Meetifyy reviewers.</li><li><strong>Transactional Communications:</strong> To send email verification codes, password reset links, account security alerts, and support replies. We do not send promotional or marketing emails.</li><li><strong>Safety and Trust:</strong> To detect abuse, investigate reported content, enforce our Community Guidelines, and respond to legal requests.</li><li><strong>Platform Improvement:</strong> To understand how the Platform is used and to fix problems and improve features.</li></ul><h2>4. Legal Basis for Processing</h2><p>Where applicable under data protection law, we rely on the following legal bases:</p><ul><li><strong>Contract:</strong> To create your account and provide the core features of the Platform you signed up for.</li><li><strong>Legitimate Interests:</strong> To maintain security, prevent abuse, improve the Platform, and provide customer support.</li><li><strong>Legal Obligations:</strong> To comply with applicable laws and respond to lawful requests from authorities.</li></ul><h2>5. Data Sharing</h2><p>We do not sell your personal information.</p><p>We share your data only in the following limited circumstances:</p><ul><li><strong>Other Users:</strong> Information you post in public communities, event pages, or on your public profile is visible to other registered users of the Platform.</li><li><strong>Infrastructure Providers:</strong> We use Supabase for authentication and database services, Cloudflare R2 for file storage, Resend for transactional email delivery, Vercel for hosting and cookieless analytics, and Sentry for anonymised error reports. These providers process data only on our behalf and under our instructions. No advertising providers receive your data, and Vercel receives only anonymous page-view and page-performance measurements.</li><li><strong>Legal and Safety Requirements:</strong> When required by law or to protect the safety, rights, or property of users or the public.</li><li><strong>Business Transfers:</strong> In the event of a merger, acquisition, or transfer of Meetifyy's operations, your data may transfer as part of that transaction. We will notify you if this occurs.</li></ul><h2>6. Your Privacy Rights</h2><p>Depending on your jurisdiction, you may have the following rights regarding your personal data:</p><ul><li><strong>Access:</strong> You can request a copy of the personal data we hold about you.</li><li><strong>Rectification:</strong> You can correct inaccurate or incomplete information through your account settings or by contacting us.</li><li><strong>Erasure:</strong> You can request the deletion of your account and associated personal data by contacting us. We will process deletion requests in accordance with our obligations and technical capabilities.</li><li><strong>Non-Discrimination:</strong> We will not treat you differently for exercising your privacy rights.</li></ul><p>Meetifyy does not currently sell personal information, and does not share personal information for cross-context behavioral advertising purposes.</p><p>To exercise any of these rights, contact us at the address below.</p><h2>7. Data Retention</h2><p>We retain your personal data for as long as your account is active and as necessary to provide the Platform, comply with legal obligations, resolve disputes, and enforce our agreements. Some data may be retained after account closure where required by law or for legitimate safety and operational reasons (for example, moderation records and reports related to serious violations).</p><p>Submitted verification photos are kept while your account exists, so that a verification decision can be reviewed, and are permanently deleted when your account is deleted. Photos that are taken but never submitted are deleted automatically, usually within 24 hours. Your verified college email remains linked to your account until you remove it in Settings or delete your account; once released, it can be verified by another account.</p><p>If you wish to request deletion of your data, please contact us directly.</p><h2>8. Security</h2><p>We take reasonable technical and organizational measures to protect your data. Authentication is handled through Supabase, which issues cryptographically signed session tokens. Passwords are never stored by Meetifyy; they are managed entirely by Supabase Auth. Data is transmitted over HTTPS. File uploads are stored in Cloudflare R2, a managed object storage service. Authentication endpoints are served without service worker caching to prevent sensitive tokens from being stored in browser cache.</p><p>No system is completely secure. We encourage you to use a strong password and to contact us immediately if you suspect unauthorized access to your account.</p><h2>9. Children's Privacy</h2><p>Meetifyy requires all users to be at least 18 years old. We do not knowingly collect personal data from anyone under 18. If we become aware that a user under 18 has registered, we will close the account and remove their data.</p><h2>10. Changes to This Policy</h2><p>We may update this Privacy Policy from time to time. When we make material changes, we will update the date at the top of this page and may notify you through the Platform or by email. We encourage you to review this policy periodically.</p><h2>11. Contact Us</h2><p>If you have questions about this Privacy Policy or wish to exercise your data rights, please reach out to us at:</p><a href="mailto:app.meetifyy@gmail.com">app.meetifyy@gmail.com</a>$legal$,
  'PUBLISHED', true, false,
  $legal$Account verification now takes one live photo, either a selfie or a government-issued ID, taken with the camera rather than uploaded; we describe that the photo is re-processed to remove location and device information.$legal$,
  TIMESTAMP '2026-10-19 00:00:00',
  NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, NULL, CURRENT_TIMESTAMP;
